Page._content:
/* 1. 亮色模式 (Light Mode) 基础设置 */
.recent-post-item,
.card-widget,
.layout > div:first-child:not(.recent-posts) {
    /* 背景：白色 85% 不透明 */
    background: rgba(255, 255, 255, 0.6) !important;
    /* 核心：毛玻璃模糊 (数值越大越模糊) */
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    /* 边框：淡淡的白边，增加立体感 */
    border: 1px solid rgba(255, 255, 255, 0.5);
    /* 阴影：柔和阴影 */
    box-shadow: 0 8px 16px -4px rgba(0,0,0,0.1);
    /* 圆角 */
    border-radius: 12px;
}

/* 2. 暗色模式 (Dark Mode) 基础设置 */
[data-theme="dark"] .recent-post-item,
[data-theme="dark"] .card-widget,
[data-theme="dark"] .layout > div:first-child:not(.recent-posts) {
    /* 背景：黑色 60% 不透明 (稍微透一点，否则太黑了) */
    background: rgba(0, 0, 0, 0.6) !important;
    /* 边框：深色模式下边框要更淡 */
    border: 1px solid rgba(255, 255, 255, 0.1);
}

/* 3. 亮色模式文字增强 (为了在花背景上看得清) */
body {
    /* 全局字体颜色稍微加深 */
    color: #333;
}
.article-title {
    /* 文章标题加粗加黑 */
    color: #000 !important;
    font-weight: bold;
}

/* 4. 暗色模式文字反白 (必须强制变白！) */
[data-theme="dark"] body {
    /* 全局正文变浅灰白 */
    color: #e0e0e0 !important;
}

[data-theme="dark"] .article-title,
[data-theme="dark"] .recent-post-info .article-title {
    /* 文章标题变亮白 */
    color: #ffffff !important;
}

[data-theme="dark"] .article-content,
[data-theme="dark"] p,
[data-theme="dark"] h1, [data-theme="dark"] h2, [data-theme="dark"] h3, 
[data-theme="dark"] h4, [data-theme="dark"] h5, [data-theme="dark"] h6 {
    /* 正文内容和标题全部变白 */
    color: #dedede !important;
}

[data-theme="dark"] .card-widget .card-content,
[data-theme="dark"] .card-widget .item-name,
[data-theme="dark"] .card-widget .author-info__name,
[data-theme="dark"] .card-widget .author-info__description {
    /* 侧边栏：用户名、简介、分类名变白 */
    color: #eeeeee !important;
}

[data-theme="dark"] a {
    /* 链接颜色：设为一种亮蓝色或浅色，防止默认的深蓝色看不清 */
    color: #61dafb; 
}
[data-theme="dark"] a:hover {
    color: #ff79c6; /* 鼠标悬停变粉色 */
}

